 function stats(){const points=Object.values(model.vertices).map(vec),box=new T.Box3().setFromPoints(points),s=box.getSize(new T.Vector3());let area=0;for(const f of model.faces){const a=f.ids.map(id=>vec(model.vertices[id]));for(let i=1;i<a.length-1;i++)area+=a[i].clone().sub(a[0]).cross(a[i+1].clone().sub(a[0])).length()/2;}q('wallSummary').textContent=`${model.faces.length} panels · ${s.x.toFixed(1)} m wide · ${s.y.toFixed(1)} m high · ${area.toFixed(1)} m²`;}
